import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr02310Controller {
  @Post('/tax-filings/simplified-payments')
  @HttpCode(200)
  async createSimplifiedPaymentStatement(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const paymentMonth = typeof data['paymentMonth'] === 'string' ? data['paymentMonth'].trim() : '';
    const incomeCategory = typeof data['incomeCategory'] === 'string' ? data['incomeCategory'].trim() : '';
    if (!/^\d{4}(0[1-9]|1[0-2])$/.test(paymentMonth)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '지급연월은 YYYYMM 형식의 6자리로 입력해 주세요.');
    }
    if (incomeCategory === '' || incomeCategory.length > 30) {
      throw new ApiError(400, 'VALIDATION_FAILED', '소득 구분은 30자 이내로 입력해 주세요.');
    }
    return transaction(async (db) => {
      // TODO: 대상 기간 지급 데이터의 테이블·컬럼이 입력에 없어 합계 집계와 PAYMENT_DATA_NOT_FOUND 확인을 하지 못함 (집계 금액은 비워 둠)
      const rows = await db.query(
        `INSERT INTO tax_filing (filing_type, payment_month, income_category, filing_status, total_amount, created_at, updated_at)
         VALUES ('SIMPLIFIED_PAYMENT', :paymentMonth, :incomeCategory, 'DRAFT', NULL, now(), now())
         RETURNING tax_filing_id AS "taxFilingId", total_amount AS "totalAmount"`,
        { paymentMonth, incomeCategory },
      );
      return rows[0];
    });
  }

  @Post('/tax-filings/:taxFilingId/file')
  @HttpCode(200)
  async fileSimplifiedPaymentStatement(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const taxFilingId = req.params['taxFilingId'];
    if (!/^\d{1,18}$/.test(taxFilingId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '세무 신고서 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT filing_status AS "filingStatus"
           FROM tax_filing
          WHERE tax_filing_id = CAST(:taxFilingId AS bigint)
            AND filing_type = 'SIMPLIFIED_PAYMENT'
          FOR UPDATE`,
        { taxFilingId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'TAX_FILING_NOT_FOUND', '간이지급명세서를 찾을 수 없습니다.');
      }
      if (found[0]['filingStatus'] !== 'DRAFT') {
        throw new ApiError(409, 'INVALID_STATE', '작성 중인 명세서만 전자신고할 수 있습니다.');
      }
      // TODO: 국세청 전자신고 연계 방식이 입력에 없어 전송과 접수 결과 반영을 하지 못함 (요청 이력만 REQUESTED로 남김)
      await db.execute(
        `INSERT INTO link_log (requester_id, link_target, link_type, status, requested_at, request_summary, created_at, updated_at)
         VALUES (CAST(:userId AS bigint), 'NTS_EFILING', '신고', 'REQUESTED', now(), :summary, now(), now())`,
        { userId: user.id, summary: '간이지급명세서 전자신고 ' + taxFilingId },
      );
      const rows = await db.query(
        `SELECT filing_status AS "filingStatus", receipt_number AS "receiptNumber", result_message AS "resultMessage"
           FROM tax_filing
          WHERE tax_filing_id = CAST(:taxFilingId AS bigint)`,
        { taxFilingId },
      );
      return rows[0];
    });
  }
}

