import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateText,
  Drawer,
  Field,
  Form,
  Num,
  TextInput,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr02310Page({ role, notify }: PageProps) {
  // 조회 API가 없어 이 화면에서 처리한 결과를 목록으로 보인다
  const [rows, setRows] = useState<Row[]>([]);
  const [creating, setCreating] = useState(false);
  const [filing, setFiling] = useState<Row | null>(null);
  const [paymentMonth, setPaymentMonth] = useState('');
  const [incomeCategory, setIncomeCategory] = useState('');

  const create = async () => {
    if (!paymentMonth.trim() || !incomeCategory.trim()) {
      throw new Error('지급연월과 소득 구분을 입력해 주세요.');
    }
    const res = await call('POST', '/tax-filings/simplified-payments', role, {
      paymentMonth: paymentMonth.trim(),
      incomeCategory: incomeCategory.trim(),
    });
    setRows([
      {
        taxFilingId: res.taxFilingId,
        paymentMonth: paymentMonth.trim(),
        incomeCategory: incomeCategory.trim(),
        totalAmount: res.totalAmount,
        filingStatus: 'DRAFT',
      },
      ...rows,
    ]);
    setCreating(false);
    setPaymentMonth('');
    setIncomeCategory('');
    notify('간이지급명세서를 작성했습니다.');
  };

  const fileIt = async () => {
    if (!filing) return;
    const res = await call('POST', '/tax-filings/' + String(filing.taxFilingId) + '/file', role, {});
    setRows(
      rows.map((r) =>
        r.taxFilingId === filing.taxFilingId
          ? {
              ...r,
              filingStatus: res.filingStatus,
              receiptNumber: res.receiptNumber,
              resultMessage: res.resultMessage,
            }
          : r,
      ),
    );
    setFiling(null);
    notify('전자신고를 요청했습니다.');
  };

  return (
    <div className="doc">
      <section className="box">
        <h2>간이지급명세서</h2>
        <Band total={rows.length}>
          <button onClick={() => setCreating(true)}>명세서 작성</button>
        </Band>
        <DataTable
          rows={rows}
          empty="아직 작성한 명세서가 없습니다. 명세서 작성 버튼으로 시작해 주세요."
          columns={[
            { key: 'paymentMonth', label: '지급연월' },
            { key: 'incomeCategory', label: '소득 구분' },
            { key: 'totalAmount', label: '집계 금액', render: (r) => <Num value={r.totalAmount} /> },
            { key: 'filingStatus', label: '신고 상태', render: (r) => <Badge value={r.filingStatus} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                r.filingStatus === 'DRAFT' ? (
                  <button className="ghost" onClick={() => setFiling(r)}>
                    전자신고
                  </button>
                ) : (
                  <span>{String(r.receiptNumber ?? '')}</span>
                ),
            },
          ]}
        />
      </section>
      {creating && (
        <Drawer title="간이지급명세서 작성" onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit="작성">
            <Field label="지급연월" required hint="YYYYMM 형식">
              <TextInput value={paymentMonth} onChange={setPaymentMonth} placeholder="202501" />
            </Field>
            <Field label="소득 구분" required>
              <TextInput value={incomeCategory} onChange={setIncomeCategory} />
            </Field>
          </Form>
        </Drawer>
      )}
      {filing && (
        <Drawer title="전자신고" onClose={() => setFiling(null)}>
          <Form
            onSubmit={fileIt}
            submit="전자신고 요청"
            danger
            note={<span>국세청에 전송하면 되돌릴 수 없습니다. 지급연월 {String(filing.paymentMonth)} 명세서를 확인한 뒤 요청해 주세요.</span>}
          />
        </Drawer>
      )}
    </div>
  );
}
